def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    best_candidate = rng.uniform(lb, ub, size=dim)
    best_func_value = func(best_candidate)

    for _ in range(budget):
        # Select a random candidate
        candidate = clip(rng.uniform(lb, ub, size=dim))

        # Refine the candidate by perturbing its neighbors
        while True:
            # Sample a neighbor of the candidate
            neighbor = candidate + rng.normal(size=dim)

            # Clip the neighbor to ensure it is within bounds
            neighbor = clip(neighbor)

            # Evaluate the function at the neighbor and compare with the best found so far
            func_value = func(neighbor)
            if func_value < best_func_value:
                best_candidate = neighbor
                best_func_value = func_value

            # If no improvement is made, stop refining this candidate
            if rng.uniform() > 0.9:
                break

    return best_candidate

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    def objective(x):
        return func(x)

    pop_size = 100
    pop = np.random.uniform(lb, ub, (pop_size, dim))
    best = None

    for i in range(budget):
        if budget % 10 == 0:
            pop = np.random.uniform(lb, ub, (pop_size, dim))

        scores = [objective(clip(x)) for x in pop]
        sorted_pop = np.array(pop)[np.argsort(scores)]

        for j in range(1, pop_size):
            trial = clip(sorted_pop[j] + rng.normal(0, 0.5) * (sorted_pop[j-1] - sorted_pop[j]))

            if objective(trial) < scores[j]:
                sorted_pop[j], trial = trial, sorted_pop[j]
                scores[j] = objective(clip(trial))

        best_candidate = clip(sorted_pop[0])
        if best is None or objective(best_candidate) < objective(best):
            best = best_candidate

    return best
